import{_ as e,c as p,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"節","description":"高岛易断 - 節","frontmatter":{"title":"節","description":"高岛易断 - 節"},"headers":[],"relativePath":"zh/classics/takashima/060.md","filePath":"zh/classics/takashima/060.md"}'),i={name:"zh/classics/takashima/060.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="節" tabindex="-1">節 <a class="header-anchor" href="#節" aria-label="Permalink to “節”">​</a></h1><h2 id="節-1" tabindex="-1">節 <a class="header-anchor" href="#節-1" aria-label="Permalink to “節”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>节：亨，苦节不可贞。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>卦体上互《艮》，“艮，止也”，下互《震》，《震》，行也；可行则行，可止则止，行止得中，乃谓之《节》。行止得中，是以能亨，若其矫枉过正，固执自守，节亦苦矣。节而苦，则无余地以处人，亦无余地以自处，有穷而无所容矣，故曰“不可贞”。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>泽上有水，节。君子以制数度，议德行。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>“泽无水”曰《困》，泽有水曰《节》，有水而不节，则泽亦涸，是以君子取象于《节》也。“数度”者，权量法度之谓也；“德行”者，道德性命之事也。《兑》自《坤》变，《坤》为重，为寡，象“数度”；《坎》自《乾》变，《乾》为道，为性，象德行，《坎》为平，谓裁制得其平也；《兑》为口，谓议论出自口也，是以君子为之“制数度，议德行”。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：运途中正，财源富有，惟宜外节出纳，内节身心。吉。</p><p>○　问战征：节制之军，登高涉险，可守可战。</p><p>○　问营商：泽有水，富饶之象。法制既精，议论亦确，无不获利也。</p><p>○　问功名：品行端正，律度精详，有鱼龙得水之象。</p><p>○　问婚姻：《坎》男《兑》女，水泽相成，吉。</p><p>○　问家宅：宅临大泽，家道富有，吉。</p><p>○　问疾病：病宜节饮食，慎行动。</p><p>○　问六甲：生男。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>初以阳居阳，为《节》之初，阳实阴虚，初当阳刚，一画塞止《兑》口，故为“不出”。上互《艮》，《艮》为牖，为居，有“户庭”之象；《艮》又为止，有不出之象，故曰“不出户庭”。卦继《涣》后，初六涣散甫集，正宜塞而不宜通也，虽户庭之近，亦不敢出，则一步一趋，无非节也，故得“无咎”。初动体《坎》，坎水为智，智则能审时度势，可通可塞，可出可入，皆有节制，故《象传》以“知通塞”释之。</p><h2 id="初九占" tabindex="-1">初九占 <a class="header-anchor" href="#初九占" aria-label="Permalink to “初九占”">​</a></h2><p>○　问时运：运途未盛，宜谨守户庭，得以免咎。</p><p>○　问营商：宜坐贾，不宜行商，无咎。</p><p>○　问功名：目下宜杜门静守，至四爻可以成名。</p><p>○　问战征：初当离散之余，军民乍聚，宜养其锐气，不宜出战。</p><p>○　问婚姻：初与四相应，四得承顺之道，即妇道之正也，故无咎。</p><p>○　问疾病：宜安居静养，无害。</p><p>○　问失物：尚在户庭之内，可寻得之。</p><p>○　问行人：尚未起行。</p><p>○　问六甲：生女。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>友人某来，请占家宅，筮得《节》之《坎》。</p><p>断曰：卦象为《兑》西《坎》北，爻象外户内庭。初居《兑》下，阳刚一画，如户庭之有锁钥，以节出入，故曰“不出户庭”；深居避祸，故曰“无咎”。今足下占家宅，得《节》初爻，此宅想是初次迁居，一切家事，正待整理，持盈保泰，宜守节俭之风，杜门谢事，可以无咎矣。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>户在内，门在外，初为户，二为门，由内而外也。初为内，坎水始至，塞之以防其漏；二则渐至于外，水既盛，宜通之，而犹曰“不出门庭”，是知塞不知通也。二爻有刚中之才，正当乘时应变，出而有为，使天下得节之用。卦自初至三互《震》，四至六互《艮》，乃不为《震》之行，而固守《艮》之止，杜门绝迹，坐失时机，是以凶也。故《象传》以失时之极斥之。</p><h2 id="九二占" tabindex="-1">九二占 <a class="header-anchor" href="#九二占" aria-label="Permalink to “九二占”">​</a></h2><p>○　问时运：运途方盛，时会亦好，咎在因循自误，为可惜也。</p><p>○　问战征：时可进取，乃畏首畏尾，固守不出，反致凶也。</p><p>○　问营商：货物充积，时价得宜，本可获利，乃因拘墟失时，反致耗损。《兑》为毁折，是失象也。</p><p>○　问功名：时会未逢，难望成名。</p><p>○　问婚姻：桃夭失时，难免旷怨，凶。</p><p>○　问家宅：门户闭锁，无人之象，凶。</p><p>○　问疾病：病由步履艰难，几成痿痹。</p><p>○　问失物：是内窃也。</p><p>○　问讼事：恐有囚禁之祸。</p><p>○　问六甲：生女。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>有警吏某氏来曰：吾友旧藩士某，维新之际，勤王死节，其后裔落魄无依。余眷念旧情，竭力赈助，以其子弟三人，招使来京，就学十数年，因之耗费，积累至六七千金，然犹以乡里田产，得值万金可偿。讵意利息倍增，迄今已万三千金矣，所有家产，又因价格低落，减数大半，欲偿则数无所出，不偿则债负不清，进退维谷，无以为计，遂至忧郁致病，不能供职。幸请教示。无已代为一占，筮得《节》之《屯》。</p><p>断曰：九二处《兑》之中，《彖传》谓“悦以行险”，二宜当之；二曰“不出门庭”，是安于陷险，而不能行险也，其不出也，故凶。足下占债负处置，得《节》二爻，爻曰“不出门庭，凶”，则知不出为凶，出则可以免凶矣。然所云“出”者有二：一则出外以避之，一则出所有以偿之，皆谓之出也。此中当必有节制矣，仆就爻辞之意，为足下债负计之。所负总数万三千金，乡里田产低价约售三干金，偿抵债主；再以月俸所得二百金内八十金为家用所费，余百二十金，亦按月归偿，合计一岁中，得偿千四百四十金。是节有余以偿不足者也，约不十年，便可清偿矣。爻辞曰“不出门庭，凶”，若明为足下戒也。足下其勿因循畏葸，坐失时机，须当出而与债主相商，先以售产之金偿之，复以月俸之余归之，让其利息，缓其限期。债主而不许，则此债必难归给，债主而许之，则足下不至破产，债主亦终得金收，彼亦何乐而不许也？《兑》为口，为友，有得朋相商之象；《兑》爻曰“商兑，未宁，介疾有喜”，正足下今日之时事也。足下速出而图之，毋失此时会也。某氏闻而心喜，曰：此最妙之策也。后数日报来云，已遵此断词，出而了事矣。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>三居《兑》之上，上画开口，为漏泽，不节之象。盖《兑》泽至三，坎水既盈，一时任意挹取，不知节省，至后将不继，不免咨嗟悔恨，故曰“不节若，则嗟若”。是为悦极生悲者，祸由己致，无所怨咎，故曰“无咎”。《象传》曰“又谁咎也”，谓当节不节，“不节”在己，“嗟若”亦在己，又将谁咎乎？</p><h2 id="六三占" tabindex="-1">六三占 <a class="header-anchor" href="#六三占" aria-label="Permalink to “六三占”">​</a></h2><p>○　问时运：壮不自检，老大徒悲，其将谁怨乎？</p><p>○　问战征：临时不谋，后悔难追。</p><p>○　问营商：当其获利，骄奢无度，一旦耗失，便致哀嗟，咎由自取耳。</p><p>○　问婚姻：有先喜后悲之象。</p><p>○　问功名：随得随失。</p><p>○　问家宅：三以阴居阳，地位不当。必致先富后贫。</p><p>○　问疾病：病由不节饮食所致，幸无大咎。</p><p>○　问失物：付之一叹，不须怨人。</p><p>○　问六甲：生女。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>明治二十年十一月，旧大垣藩主户田氏共伯，任澳大利亚全权公使，偕眷属赴任，临发横滨，枉驾余宅。此时送者不下数十人，伯曰：请占海上平安。筮得《节》之《需》。</p><p>断曰：三爻居内外卦之交，正合贵下出外远行之兆；《坎》为水，兑为泽，有大海之象。三动体《需》，《需》《彖》曰“险在前也”，知此行防有险难。卦反《涣》，《涣》象为“风行水上”，知必有风；《兑》正西，《坎》正北，知其风必自西而北。爻曰“不节若，则嗟若”，谓非秉节而行，必致咨嗟。今贵下皇华出使，节钺在身，必能使海若效顺，百神呵护，即遇风险，必无咎也。《需》《彖》辞又曰“利涉大川，往有功也”，是可为贵下贺焉。时送行者，如旧藩臣《井》田五藏，青森县知事菱田文藏、大审院判事鸟居断三、神道教正鸿雪爪《咸》皆在座，倾听之余，或谓照此判词，海上风波，浑如眼见，未来之事，皆得前知，疑余臆断，未必可信也。鸿雪爪君独云：高岛君《易》筮，素称入神，多为人所不《解》者也。余曰：余惟凭爻而断，应与不应，非余所知，然向所断，未尝有或爽者，殆可谓如响斯应者矣。诸士惟惟，不复有言。后四年，户田伯归朝，告余以当时海上困难，一如《易》断。</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>四本《坤》体，《坤》为安，故曰“安”；居《坎》之始，《坎》为险，以《兑》节之，斯得化险为安，故曰“安节”。“安节”者，安而行之，不失其节，则何往不通？故曰“安节，亨”。四得位承五，五“中正以通”，四先通之，是以《彖》之亨，惟归于四；四以承五得亨，而天下无不亨矣。《象传》曰“承上道也”，上指五，道即《节》之道，谓五以节风示天下，四比近五，能首承其道也。</p><h2 id="六四占" tabindex="-1">六四占 <a class="header-anchor" href="#六四占" aria-label="Permalink to “六四占”">​</a></h2><p>○　问时运：一路平安。</p><p>○　问战征：善战者在先安军心，军心安，则临危不惧，而所向有功。</p><p>○　问营商：四在外卦之始，必是初次贩货出外，能事事节俭，斯得安居外地，而所谋亦得亨通矣。</p><p>○　问功名：能承上意，必得成名。</p><p>○　问婚姻：四以阴居阴，得位承阳，自得家室安全。</p><p>○　问家宅：平安获吉。</p><p>○　问疾病：病由口入，能节饮食，自得安泰。</p><p>○　问六甲：生男。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>官吏某来，请占官位升迁，筮得《节》之《兑》。</p><p>断曰：六四重阴，爻象安静，事事中节，是以亨也。《象传》曰“承上道也”，上谓五，四与五比，能承上旨而行节也。今足下占官途升迁，得《节》四爻，四与初应，初“知通塞”，故四能安分守己，不失其节。惟承上之意旨而行，是以发皆中节，无往而不亨通也，升迁必矣。四与五间一爻，升迁当在明年。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>五居尊位，为《节》之主，《彖》所谓“当位以节，中正以通”，惟五当之。《彖》首戒“苦节，不可贞”，反苦为甘，其道必贞，贞则吉矣，故曰“甘节，吉”。四居《坎》中，《坎》《彖》曰“行有尚”，《节》四之“往有尚”，盖即由《坎》《彖》而来。“往”即“行”，谓能行斯而往，洵可嘉尚。按五味以甘为得中，咸苦酸辛，皆偏也。节味之偏，而适其中，谓之“甘节”，甘则人皆乐从，而不病其难也，此“甘节”之所以为吉也。《象传》以“居位中”释之，《礼·月令》白，“中央土，其味甘”，甘位居中，五为君，君位亦居中，《象传》所释之意取此。</p><h2 id="九五占" tabindex="-1">九五占 <a class="header-anchor" href="#九五占" aria-label="Permalink to “九五占”">​</a></h2><p>○　问时运：运如嚼蔗，到老愈甘。</p><p>○　问营商：稼穑作甘，当以贩运谷米为吉。“往有尚”，往者往外也，尤当贩米，往外洋销售，定必获利。</p><p>○　问功名：苦尽甘来，功名必显。</p><p>○　问家宅：五爻得位，中央为甘，知此宅必地位中正，家风正直，节俭足以嘉尚。</p><p>○　问婚姻：女之嫁曰往“往有尚”，谓往而成礼。“甘”者，甘心相从，有百年好合之象，吉。</p><p>○　问疾病：病在中宫，甘则中满，须宜节食为要。</p><p>○　问六甲：生男。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>某商人来，请占商业盈亏，筮得《节》之《临》。</p><p>断曰：味之甘者，人所乐嗜，然过甘则味亦变，节之所以适其中，于味然，于万事亦无不然。“往有尚”者，谓由此以往，事皆可尚，事皆获吉矣。今足下占商业盈亏，得《节》四爻，知足下于商业，经营已久，向以不知撙节，致来嗟恨。去岁得安，今年又必获甘味，所当裁而节之。事事从节，毋以盈满自侈，斯盈可长保其盈矣，故吉。“往”者，为遵此《节》道以往，“往有尚”，亦往有功也。足下此后，商业大利。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>六重阴不中，居《节》之极，是过《节》者。《尔雅》，“卤，咸苦也”，坎水润下作咸。《兑》为刚卤，是味之苦者也。上与初相终始，初在泽底，节以防漏，上在泽口，出纳由之，而竟概节之，是不知通塞也，其困苦之状，物所难堪，有不可终日者矣，故《彖》之“苦节”，独归于上。“悔亡”者，谓奢不如俭，以此修身，悔自亡矣。《传》曰“道穷”，即以释《彖》者释之。“苦节，贞凶”者，自古之龙逢比干，为国亡身，克全臣节，其祸虽凶，其道则正，足以表式万世，复有何悔？</p><h2 id="上六占" tabindex="-1">上六占 <a class="header-anchor" href="#上六占" aria-label="Permalink to “上六占”">​</a></h2><p>○　问时运：运途亦正，为固执不通，以致终身穷苦。</p><p>○　问营商：机会已极，不知变通，以致穷迫，徒自苦耳。</p><p>○　问功名：其人则守正不阿，困苦自守，难望成名。</p><p>○　问战征：爻象重阴，柔弱无力，又当地穷势极，只知苦守不出，终必凶矣。</p><p>○　问疾病：阴盛阳衰，病势已极，凶。</p><p>○　问六甲：生男。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>有商友某氏，请占株式高下，筮得《节》之《中孚》。</p><p>断曰：此卦泽上有水之象，泽有水，盈则通之，不盈则塞之。通塞者，是为水之节制也，上爻当泽之上口，宜通而塞，是过于节也。水流而不止，流水甘也，上塞而不流，则为停潦，甘亦苦矣，故曰“苦节，贞凶”。今足下占株式高低，得此爻象，株式者，财用之资，财源犹如水源，宜流通，不宜壅塞；况上爻当时位已极，若塞而不穷，好为垄断，以期高价，令人迫蹙困苦，无以为生，防苦极生变，则苦人者反而自苦，取凶之道，亦取穷之道也。宜速开通，斯可免凶矣。其人闻之，即日卖脱。后其价随即低落。</p><p>三十一年，占北海道厅之治象，筮得《节》之《中孚》。</p><p>断曰：上爻当兑泽之口，坎流既盈，又复节而不通，令人不得沾其惠泽，是谓“苦节，”其道必凶。今占北海道厅政治，得此爻象，知其施政，有不合地势，不通民情，上下拥塞，号令不行之象。上爻动为《中孚》，当速变通出之，斯可孚而化邦也。就外象论之，兑泽水盈，盈则必溢，《兑》，秋也，防秋时有洪水之灾。是年九月，果有水难，人民苦之，凶象如是。</p><p>三十一年，占外交形势，筮得《节》之《中孚》。</p><p>断曰：上爻之“苦节”，是过节者也，节得其中则甘，过之则苦。天下事皆贵适中，过则困苦随之，凶祸亦随之矣，是势所必然也。今占外交，得此爻象，知当今时势，正是泽水满溢，岌岌可危之际，所宜流通四海，变其节制，以适权宜，斯可免受困苦。若竟吝而不出，固执自守，其凶必矣。</p>',108)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
